from pathlib import Path
import re

GENERIC_STARTS = [
    'در پروژه‌های حساس، بهتر است پس از نصب و راه‌اندازی، بازخورد واقعی بهره‌بردار',
    'در پروژه‌های حساس، قبل از خرید باید مشخص شود برند مورد نظر در Vendor List',
    'برای خرید برندمحور، بهتر است فروشنده تصویر پلاک، دیتاشیت رسمی، شرایط گارانتی',
]

def visible(s):
    return re.sub(r'\s+',' ', re.sub(r'<[^>]+>',' ',s)).strip()

def remove_generic_paras(html):
    def repl(m):
        t = visible(m.group(1))
        return '' if any(t.startswith(x) for x in GENERIC_STARTS) else m.group(0)
    return re.sub(r'<p\b[^>]*>([\s\S]*?)</p>', repl, html)

